args.command:
node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
for (const [path, title, description, heading, copy, link] of [
  ['/', 'Home Page', 'Welcome to our Next.js app', 'Home', 'Welcome to our Next.js application!', '/about'],
  ['/about', 'About Us', 'Learn more about us', 'About', 'This is the about page of our Next.js application.', '/'],
]) {
  const response = await fetch(`http://localhost:3017${path}`)
  const html = await response.text()
  assert.equal(response.status, 200, `${path} status`)
  for (const expected of [`<html lang="en"`, `<title>${title}</title>`, `content="${description}"`, `<h1>${heading}</h1>`, copy, `href="${link}"`, `href="/contact"`, `href="/favicon.ico"`, 'width=device-width, initial-scale=1']) {
    assert.ok(html.includes(expected), `${path}: missing ${expected}`)
  }
  console.log(`${path}: 200; title, description, content, links, viewport, icon OK`)
}
const contact = await fetch('http://localhost:3017/contact')
assert.equal(contact.status, 404)
console.log('/contact: 404 (unchanged)')
